# Batch Processing Pattern for Document Classification

## Overview
A complete pattern for processing many documents efficiently.

## Full Implementation
```python
import os
import re
import shutil
import fitz  # PyMuPDF
from docx import Document
from pptx import Presentation

# Category keywords
CATEGORIES = {
    "LLM": ["language model", "llm", "transformer", "gpt", "bert", "nlp",
            "neural network", "attention", "chatgpt", "prompt", "embedding",
            "generative ai", "large language", "fine-tuning", "tokenization"],
    "trapped_ion_and_qc": ["trapped ion", "quantum", "qubit", "ion trap",
                          "quantum computing", "quantum gate", "entanglement",
                          "quantum processor", "decoherence", "superconducting"],
    "black_hole": ["black hole", "event horizon", "hawking", "singularity",
                   "gravitational", "general relativity", "spacetime",
                   "schwarzschild", "accretion", "photon sphere"],
    "DNA": ["dna", "rna", "genome", "gene", "nucleotide", "chromosome",
            "genetic", "sequencing", "crispr", "mutation", "protein",
            "amino acid", "helix", "transcription", "polymerase"],
    "music_history": ["music history", "composer", "symphony", "baroque",
                      "classical music", "romantic period", "opera",
                      "beethoven", "mozart", "bach", "musicology"]
}

def extract_pdf_text(path, max_pages=3):
    try:
        doc = fitz.open(path)
        text = "".join(doc[i].get_text() for i in range(min(max_pages, len(doc))))
        doc.close()
        return text
    except:
        return ""

def extract_docx_text(path):
    try:
        doc = Document(path)
        return "\n".join(p.text for p in doc.paragraphs)
    except:
        return ""

def extract_pptx_text(path):
    try:
        prs = Presentation(path)
        text = ""
        for slide in prs.slides:
            for shape in slide.shapes:
                if hasattr(shape, "text"):
                    text += shape.text + "\n"
        return text
    except:
        return ""

def extract_text(path):
    ext = path.lower().split('.')[-1]
    if ext == 'pdf':
        return extract_pdf_text(path)
    elif ext == 'docx':
        return extract_docx_text(path)
    elif ext == 'pptx':
        return extract_pptx_text(path)
    return ""

def classify(text):
    text_lower = text.lower()
    scores = {}
    for cat, keywords in CATEGORIES.items():
        score = sum(len(re.findall(r'\b' + re.escape(kw) + r'\b', text_lower))
                   for kw in keywords)
        scores[cat] = score

    if max(scores.values()) == 0:
        return "music_history"  # Default fallback
    return max(scores, key=scores.get)

def main(source_dir, dest_dir):
    # Create destination folders
    for cat in CATEGORIES:
        os.makedirs(os.path.join(dest_dir, cat), exist_ok=True)

    # Process each file
    results = {cat: [] for cat in CATEGORIES}
    for filename in os.listdir(source_dir):
        path = os.path.join(source_dir, filename)
        if not os.path.isfile(path):
            continue

        text = extract_text(path)
        category = classify(text)

        dest_path = os.path.join(dest_dir, category, filename)
        shutil.move(path, dest_path)
        results[category].append(filename)
        print(f"{filename} -> {category}")

    # Summary
    print("\n=== Summary ===")
    for cat, files in results.items():
        print(f"{cat}: {len(files)} files")

if __name__ == "__main__":
    main("./papers/all", "./papers")
```

## Key Points
1. Extract only first few pages of PDFs (title + abstract is usually enough)
2. Use fallback category for unclassifiable documents
3. Handle exceptions silently to continue processing
4. Print progress and summary for monitoring

